script:
(function () {
  'use strict';
  // Deferred payment loan: no principal payments for D months, then a standard amortizing loan.
  // Monthly rate i = APR / 12. Interest during the deferral is handled one of three ways:
  //   compound - added to the balance each month: B = L(1 + i)^D
  //   simple   - accrues on the original amount, added when repayment starts: B = L(1 + iD)
  //   paid     - interest-only payments of L x i each month: B = L
  // Then M = B x i / (1 - (1 + i)^-n) for n repayment months (B / n at 0%); the final payment
  // clears the balance exactly. The no-deferral comparison amortizes L over n months from today.
  // Verified (Node, scratchpad tests/g1031_dpl.test.js) against an independent calculation:
  //   $20,000 at 7%, 12 months deferred, 60-month repayment: compound -> balance $21,445.80,
  //   payment $424.65; simple -> $21,400.00, $423.75; paid -> $116.67 a month, then $396.02;
  //   no deferral -> $396.02, total interest $3,761.44 (compound deferral costs $1,717.72 more); the month-by-month schedule sums to the
  //   closed form within a cent. 0% rate -> no interest, $20,000 / 60 = $333.33. 0 months deferral
  //   matches the no-deferral loan. Invalid input shows an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var last = null;

  function el(id) { return document.getElementById(id); }
  function setText(id, t) { el(id).textContent = t; }
  function read(id) {
    var raw = String(el(id).value).trim();
    if (raw === '') return NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function pmt(bal, i, n) {
    if (bal <= 0 || n <= 0) return 0;
    if (i === 0) return bal / n;
    return bal * i / (1 - Math.pow(1 + i, -n));
  }

  function build(loan, apr, defer, term, mode) {
    var i = apr / 100 / 12, bal = loan, rows = [], accrued = 0, deferInt = 0, deferPaid = 0;
    for (var m = 1; m <= defer; m++) {
      var int = loan * i;
      if (mode === 'compound') { int = bal * i; bal += int; }
      else if (mode === 'simple') { accrued += int; }
      else { deferPaid += int; }
      deferInt += int;
      var balOut = mode === 'simple' ? bal + accrued : bal;
      if (mode === 'simple' && m === defer) { bal += accrued; balOut = bal; }
      rows.push({ n: m, phase: 'defer', paid: mode === 'paid' ? int : 0, interest: int, principal: 0, balance: balOut });
    }
    var startBal = bal, pay = pmt(bal, i, term), repayInt = 0, repayPaid = 0;
    for (var k = 1; k <= term && bal > 0.000001; k++) {
      var it = bal * i, pr = Math.min(pay - it, bal);
      if (k === term) pr = bal;
      bal -= pr;
      if (Math.abs(bal) < 0.000001) bal = 0;
      repayInt += it; repayPaid += pr + it;
      rows.push({ n: defer + k, phase: 'repay', paid: pr + it, interest: it, principal: pr, balance: bal });
    }
    return { rows: rows, startBal: startBal, payment: pay, deferInt: deferInt, deferPaid: deferPaid, repayInt: repayInt,
      totalInt: deferPaid + repayPaid - loan, totalPaid: deferPaid + repayPaid };
  }

  function render() {
    var body = el('dplSchedule'), head = el('dplHead');
    if (!last) { body.innerHTML = ''; return; }
    var cols = '<th scope="col">Paid</th><th scope="col">Interest charged</th><th scope="col">Balance repaid</th><th scope="col">Ending balance</th>';
    var html = [];
    if (el('dplView').value === 'month') {
      head.innerHTML = '<tr><th scope="col">Month</th>' + cols + '</tr>';
      last.rows.forEach(function (r) {
        html.push('<tr><td>' + r.n + (r.phase === 'defer' ? ' (deferred)' : '') + '</td><td>' + money.format(r.paid) + '</td><td>' +
          money.format(r.interest) + '</td><td>' + money.format(r.principal) + '</td><td>' + money.format(r.balance) + '</td></tr>');
      });
    } else {
      head.innerHTML = '<tr><th scope="col">Year</th>' + cols + '</tr>';
      var p = 0, it = 0, pr = 0;
      last.rows.forEach(function (r, idx) {
        p += r.paid; it += r.interest; pr += r.principal;
        if (r.n % 12 === 0 || idx === last.rows.length - 1) {
          html.push('<tr><td>' + Math.ceil(r.n / 12) + '</td><td>' + money.format(p) + '</td><td>' + money.format(it) + '</td><td>' +
            money.format(pr) + '</td><td>' + money.format(r.balance) + '</td></tr>');
          p = 0; it = 0; pr = 0;
        }
      });
    }
    body.innerHTML = html.join('');
  }

  var IDS = ['dplPayment', 'dplStartBal', 'dplInterest', 'dplTotal', 'dplDeferInt', 'dplDeferPay', 'dplRepayInt', 'dplMonths', 'dplNoPay', 'dplNoInt', 'dplExtra'];

  function update() {
    var loan = read('dplLoan'), rate = read('dplRate'), defer = read('dplDefer'), term = read('dplTerm'), mode = el('dplMode').value;
    var err = el('dplError'), msg = '';
    if ([loan, rate, defer, term].some(isNaN)) msg = 'Fill in every field with a number.';
    else if (loan <= 0 || loan > 1e10) msg = 'Enter a loan amount above $0.';
    else if (rate < 0 || rate > 50) msg = 'Enter an interest rate from 0% to 50%.';
    else if (defer < 0 || defer > 120 || Math.round(defer) !== defer) msg = 'Enter a deferral of 0 to 120 whole months.';
    else if (term < 1 || term > 480 || Math.round(term) !== term) msg = 'Enter a repayment term of 1 to 480 whole months.';
    err.hidden = !msg;
    err.textContent = msg;
    if (msg) { IDS.forEach(function (id) { setText(id, '–'); }); last = null; render(); return; }

    var r = build(loan, rate, defer, term, mode), base = build(loan, rate, 0, term, mode);
    last = r;
    setText('dplPayment', money.format(r.payment));
    setText('dplStartBal', money.format(r.startBal));
    setText('dplInterest', money.format(r.totalInt));
    setText('dplTotal', money.format(r.totalPaid));
    setText('dplDeferInt', money.format(r.deferInt) + (mode === 'paid' ? ' (paid as you go)' : defer > 0 ? ' (added to the balance)' : ''));
    el('dplDeferPayRow').hidden = mode !== 'paid';
    setText('dplDeferPay', money.format(loan * rate / 100 / 12));
    setText('dplRepayInt', money.format(r.repayInt));
    setText('dplMonths', String(defer + term));
    setText('dplNoPay', money.format(base.payment));
    setText('dplNoInt', money.format(base.totalInt));
    setText('dplExtra', money.format(Math.max(0, r.totalInt - base.totalInt)));
    render();
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('dplForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    el('dplView').addEventListener('change', render);
    update();
  });
})();
